import{_ as r,o as d,c as a,a3 as o}from"./chunks/framework.qCVWde4n.js";const p=JSON.parse('{"title":"Mod 仓库总览","description":"","frontmatter":{},"headers":[],"relativePath":"repo/start.md","filePath":"repo/start.md","lastUpdated":1791133906000}'),e={name:"repo/start.md"};function s(n,t,i,l,h,c){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="mod-仓库总览" tabindex="-1">Mod 仓库总览 <a class="header-anchor" href="#mod-仓库总览" aria-label="Permalink to &quot;Mod 仓库总览&quot;">​</a></h1><p>Mod 仓库是一个<strong>网页版的作品集散地</strong>：玩家在手机浏览器里搜 Mod、看详情、复制分享码，然后回游戏粘贴就能用。</p><p>访问地址：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://atlanticfleet.asia/mods/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="为什么是网页-而不是游戏内的市场" tabindex="-1">为什么是网页，而不是游戏内的市场 <a class="header-anchor" href="#为什么是网页-而不是游戏内的市场" aria-label="Permalink to &quot;为什么是网页，而不是游戏内的市场&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">这是一个有意的取舍</p><p>看起来「在游戏内做一个创意工坊」更酷，但实际上：</p><ul><li>游戏内加网络栈要引入 HTTP 客户端 + TLS + 超时重试，在<strong>老 Mono 运行时上风险很高</strong></li><li>一旦出问题是<strong>启动即崩</strong>，而崩了玩家连日志都拿不到</li></ul><p>所以改成「<strong>网页浏览 + 分享码导入</strong>」：游戏侧<strong>零改动</strong>，复用了已有的分享码能力。</p><p>结果是——网页上一键复制分享码，回游戏粘贴导入，体验其实比想象中顺。</p></div><h2 id="这个仓库给三种人用" tabindex="-1">这个仓库给三种人用 <a class="header-anchor" href="#这个仓库给三种人用" aria-label="Permalink to &quot;这个仓库给三种人用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你是</th><th>去哪</th></tr></thead><tbody><tr><td><strong>玩家</strong> —— 想找 Mod 装</td><td><a href="/AtlanticFleetSite/docs/repo/browse">浏览与安装（玩家）</a></td></tr><tr><td><strong>作者</strong> —— 想发自己的 Mod</td><td><a href="/AtlanticFleetSite/docs/repo/publish">上传你的 Mod（作者）</a></td></tr><tr><td><strong>站长</strong> —— 想维护 / 备份</td><td><a href="/AtlanticFleetSite/docs/repo/admin">审核后台（站长）</a></td></tr></tbody></table><h2 id="网页有哪些功能" tabindex="-1">网页有哪些功能 <a class="header-anchor" href="#网页有哪些功能" aria-label="Permalink to &quot;网页有哪些功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><strong>搜索</strong></td><td>按名字 / 作者 / 说明 / 标签搜</td></tr><tr><td><strong>排序</strong></td><td>最新 / 最热 / 名称</td></tr><tr><td><strong>详情弹层</strong></td><td>点卡片看完整说明 + <strong>这个 Mod 改了哪些参数</strong>（自动标出调高 ↑ / 调低 ↓）</td></tr><tr><td><strong>一键复制分享码</strong></td><td>粘到任意聊天窗口就能发出去</td></tr><tr><td><strong>下载包体</strong></td><td>想手动装的人用</td></tr><tr><td><strong>★ 网页上传</strong></td><td>作者直接在网页填表上传，管理员过审后上架</td></tr><tr><td><strong>★ 审核后台</strong></td><td>站长在 <code>/admin/</code> 里审 / 驳回 / 下架 / 删除，全程留痕</td></tr><tr><td><strong>★ 分享码解析器</strong></td><td>收到陌生码，粘进网页就知道是什么、谁写的、改了什么</td></tr></tbody></table><h2 id="技术上是怎么做的" tabindex="-1">技术上是怎么做的 <a class="header-anchor" href="#技术上是怎么做的" aria-label="Permalink to &quot;技术上是怎么做的&quot;">​</a></h2><p>仓库由<strong>静态网页 + 一个轻量后端</strong>组成：</p><table tabindex="0"><thead><tr><th>部分</th><th>作用</th></tr></thead><tbody><tr><td><strong>网页</strong></td><td><code>mods/</code>（仓库页 + 上传区 + 分享码解析）、<code>admin/</code>（审核后台）</td></tr><tr><td><strong>后端服务</strong></td><td>一个<strong>零依赖</strong>的 Python 脚本，负责收上传、存数据、生成分享码</td></tr><tr><td><strong>仓库清单</strong></td><td><code>index.json</code>，网页与游戏端读的是<strong>同一份数据</strong></td></tr><tr><td><strong>可下载的包</strong></td><td><code>packages/</code> 下每个 Mod 的 <code>.json</code> + <code>.txt</code> 分享码</td></tr></tbody></table><p>后端<strong>不需要任何第三方库、不需要数据库</strong>（数据用 SQLite 单文件存），架设成本很低。</p><p>详细的作者 / 站长操作见 <a href="/AtlanticFleetSite/docs/repo/publish">上传你的 Mod（作者）</a> 与 <a href="/AtlanticFleetSite/docs/repo/admin">审核后台（站长）</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>装 Mod → <a href="/AtlanticFleetSite/docs/repo/browse">浏览与安装（玩家）</a></li><li>发 Mod → <a href="/AtlanticFleetSite/docs/repo/publish">上传你的 Mod（作者）</a></li><li>维护 → <a href="/AtlanticFleetSite/docs/repo/admin">审核后台（站长）</a></li></ul><h2 id="遇到问题找谁" tabindex="-1">遇到问题找谁 <a class="header-anchor" href="#遇到问题找谁" aria-label="Permalink to &quot;遇到问题找谁&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想做什么</th><th>去哪</th></tr></thead><tbody><tr><td>装的 Mod 出问题了</td><td><strong><a href="/AtlanticFleetSite/docs/faq">常见问题</a></strong> 覆盖了八成问题；剩下的看下面的<a href="/AtlanticFleetSite/docs/changelog">更新日志</a>里有没有相关改动</td></tr><tr><td>看开发进展</td><td><a href="/AtlanticFleetSite/docs/changelog">更新日志</a> —— 每个版本改了什么都在这里</td></tr><tr><td>直接去仓库网页</td><td><a href="https://atlanticfleet.asia/mods/" target="_blank" rel="noreferrer">Mod 分享仓库</a></td></tr></tbody></table>',19)])])}const b=r(e,[["render",s]]);export{p as __pageData,b as default};
